<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {api} from '../lib/api'
import {friendlyError} from '../lib/format'
import type {MatterDocument} from '../lib/types'
const props=defineProps<{matterId:string;documents:MatterDocument[];ids:string[];disabled:boolean}>()
const emit=defineEmits<{modified:[];close:[];dirtyChanged:[value:boolean]}>()
type Suggestion={document_id:string;original_name:string;revision:number;source_sha256:string;page:number;group_key:string;field:'title'|'document_date';current:string;proposed:string;status:'proposed'|'uncertain'|'unavailable';source:string;evidence:string;evidence_id:string;note:string;available?:boolean}
type Draft={value:string;selected:boolean;dismissed:boolean}
const result=ref<{input_snapshot:string;rows:Suggestion[];document_versions:Record<string,string>}|null>(null),drafts=reactive<Record<string,Draft>>({}),pages=reactive<Record<string,number>>({})
const sourceZoom=ref(false)
const loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),filter=ref('all'),selected=ref(props.ids[0]||''),sort=ref(false),drawer=ref(false),stale=ref(false)
let sourceInvoker:HTMLElement|null=null
async function openSource(){sourceInvoker=document.activeElement as HTMLElement;drawer.value=true;await nextTick();if(window.matchMedia('(max-width:1100px)').matches)document.querySelector<HTMLElement>('.source-review .review-check input')?.focus()}
async function closeSource(){drawer.value=false;await nextTick();sourceInvoker?.focus()}
const preview=ref<{image:string;revision:number;page:number}|null>(null),previewError=ref(''),previewLoading=ref(false)
let sequence=0,previewSequence=0,alive=true
const key=(r:Suggestion)=>r.document_id+':'+r.field
const pending=computed(()=>(result.value?.rows||[]).filter(r=>!drafts[key(r)]?.dismissed))
const visible=computed(()=>pending.value.filter(r=>filter.value==='all'||(filter.value==='proposed'?r.status==='proposed':r.field==='document_date'&&r.status!=='proposed')))
const current=computed(()=>props.documents.find(d=>d.id===selected.value))
const selectedRows=computed(()=>(result.value?.rows||[]).filter(r=>r.document_id===selected.value&&!drafts[key(r)]?.dismissed))
function valid(r:Suggestion){const value=drafts[key(r)]?.value.trim()||'';if(!value||value.length>250||/[\x00-\x1f]/.test(value))return false;if(r.field==='title')return true;if(!r.available||!/^\d{4}-\d{2}-\d{2}$/.test(value))return false;const d=new Date(value+'T00:00:00Z');return Number.isFinite(d.getTime())&&d.toISOString().slice(0,10)===value}
const accepted=computed(()=>pending.value.filter(r=>drafts[key(r)]?.selected&&valid(r)))
const dirty=computed(()=>sort.value||Object.entries(drafts).some(([k,d])=>!d.dismissed&&(d.selected||d.value!==(result.value?.rows.find(r=>key(r)===k)?.proposed||''))))
watch(dirty,v=>emit('dirtyChanged',v),{immediate:true})
watch(()=>props.documents,()=>{if(result.value&&!saving.value){const versions=result.value.document_versions;stale.value=props.documents.length!==Object.keys(versions).length||props.documents.some(d=>versions[d.id]!==d.updated_at)}})
watch(selected,()=>{sort.value=false;sourceZoom.value=false})
function discard(){sort.value=false;for(const r of result.value?.rows||[])drafts[key(r)]={value:r.proposed,selected:false,dismissed:false}}
async function load(retain?:Record<string,Draft>){const seq=++sequence;loading.value=true;error.value='';preview.value=null;try{const r=await api<NonNullable<typeof result.value>>(`/matters/${props.matterId}/metadata-suggestions`,'POST',{ids:props.ids,pages});if(!alive||seq!==sequence)return;result.value=r;stale.value=false;discard();if(retain)for(const [k,d] of Object.entries(retain))if(drafts[k])drafts[k]=d;if(!props.ids.includes(selected.value))selected.value=props.ids[0]||'';await loadPreview()}catch(e){if(alive&&seq===sequence)error.value=friendlyError(e)}finally{if(alive&&seq===sequence)loading.value=false}}
async function loadPreview(){const seq=++previewSequence;preview.value=null;previewError.value='';const row=result.value?.rows.find(r=>r.document_id===selected.value);if(!row)return;previewLoading.value=true;try{const r=await api<NonNullable<typeof preview.value>>(`/documents/${row.document_id}/metadata-source?revision=${row.revision}&page=${row.page}`);if(alive&&seq===previewSequence)preview.value=r}catch(e){if(alive&&seq===previewSequence)previewError.value=friendlyError(e)}finally{if(alive&&seq===previewSequence)previewLoading.value=false}}
watch(selected,()=>void loadPreview())
function select(r:Suggestion){selected.value=r.document_id;void openSource()}
function dismiss(r:Suggestion){drafts[key(r)].dismissed=true;drafts[key(r)].selected=false;notice.value='Suggestion dismissed for this review. Saved metadata is unchanged.'}
async function save(){if(saving.value||loading.value||stale.value||!accepted.value.length)return false;saving.value=true;error.value='';const acceptedKeys=new Set(accepted.value.map(key));const retained=Object.fromEntries(Object.entries(drafts).filter(([k])=>!acceptedKeys.has(k)).map(([k,d])=>[k,{...d}]));try{await api(`/matters/${props.matterId}/metadata-suggestions/accept`,'POST',{ids:props.ids,pages,expected_snapshot:result.value!.input_snapshot,fields:accepted.value.map(r=>({document_id:r.document_id,field:r.field,value:drafts[key(r)].value.trim(),evidence_id:r.evidence_id})),sort_group:sort.value?current.value?.group_key:null});discard();emit('modified');await load(retained);notice.value='Selected fields accepted. Recalculate the index and rebuild affected output.';return true}catch(e){error.value=friendlyError(e);if(error.value.includes('stale')||error.value.includes('changed'))stale.value=true;return false}finally{saving.value=false}}
defineExpose({save,discard,hasPendingDraft:()=>dirty.value})
onBeforeUnmount(()=>{alive=false;sequence++;previewSequence++})
void load()
</script>
<template>
<section class="metadata-review" aria-label="Review title and date suggestions">
 <header class="metadata-heading"><div><h1>Review title &amp; date suggestions</h1><p>Suggestions from filenames and source pages · Review the evidence before changing document metadata.</p></div><button class="membership-button primary" :disabled="disabled||saving||loading||stale||!accepted.length" @click="save">{{saving?'Accepting…':`Accept ${accepted.length} suggestions`}}</button></header>
 <nav class="metadata-filters" aria-label="Suggestion filters"><button v-for="f in [{id:'all',label:'All suggestions',count:pending.length},{id:'proposed',label:'Proposed values',count:pending.filter(r=>r.status==='proposed').length},{id:'uncertain',label:'Uncertain date',count:pending.filter(r=>r.field==='document_date'&&r.status!=='proposed').length}]" :key="f.id" :class="['membership-button',filter===f.id?'primary':'quiet']" :aria-pressed="filter===f.id" @click="filter=f.id">{{f.label}} · {{f.count}}</button><button class="text-tool review-back" @click="emit('close')">Back to batch review</button></nav>
 <p v-if="loading" role="status">Reading local filenames and selected source pages…</p><p v-if="error" role="alert" class="review-error">{{error}} <button v-if="!stale" class="text-tool" @click="result?save():load()">Retry</button></p><p v-if="stale" class="review-error" role="status">Review is stale. Your draft is retained. <button class="text-tool" @click="load()">Discard proposals and reload evidence</button></p><p v-if="notice" role="status" class="review-notice">{{notice}}</p>
 <div class="metadata-grid" v-if="result&&!loading">
  <section class="metadata-card suggestion-list"><h2>Suggested metadata</h2><p class="review-context">Selected document: {{current?.original_name||'None'}}</p><div class="suggestion-table-scroll"><table class="suggestion-table"><thead><tr><th>Document</th><th>Field</th><th>Suggested value</th><th>Evidence</th></tr></thead><tbody><tr v-for="r in visible" :key="key(r)" :class="{'suggestion-active':r.document_id===selected}"><td><button class="source-row-button" @click="select(r)">{{r.original_name}}</button></td><td>{{r.field==='title'?'Title':'Date'}}</td><td><span>{{drafts[key(r)].value||'Needs manual review'}}</span><small>Current: {{r.current||'Blank'}}</small><small v-if="drafts[key(r)].selected">{{valid(r)?'Selected for acceptance':'Invalid — not selected for saving'}}</small></td><td><button class="text-tool" @click="select(r)">{{r.source==='filename'?'Filename':`Page ${r.page}`}}</button><small :title="r.evidence">{{r.evidence}}</small></td></tr></tbody></table><p v-if="!visible.length" class="review-empty">No suggestions in this filter. Saved metadata is unchanged.</p></div><footer class="suggestion-list-footer"><label class="review-check"><input v-model="sort" type="checkbox" :disabled="!current?.group_key||saving"/>Sort this group by accepted dates<span v-if="current?.group_key"> · {{current.group_key}}</span></label><p>Sorting is a separate choice. Confirmed dates first; unknown dates last. Equal dates retain their order. Other groups stay in place.</p><button class="text-tool" @click="load()" :disabled="dirty||saving">Refresh suggestions</button><button class="text-tool compact-source-button" @click="openSource">Review selected source</button></footer></section>
  <section :class="['metadata-card source-review',{'source-open':drawer}]" @keydown.esc="closeSource" aria-label="Review the source"><header><h2>Review the source</h2><button class="text-tool" :aria-pressed="sourceZoom" @click="sourceZoom=!sourceZoom">{{sourceZoom?'Fit source width':'Enlarge source'}}</button><button class="text-tool compact-source-button" @click="closeSource">Close source</button></header><p class="review-context">{{current?.title}} · Working r{{selectedRows[0]?.revision}} · Source {{selectedRows[0]?.page}} / {{current?.page_count}}</p><div class="metadata-source-page"><p v-if="previewLoading" role="status">Rendering source page…</p><p v-else-if="previewError" role="alert">{{previewError}} <button class="text-tool" @click="loadPreview">Retry source</button></p><img v-else-if="preview" :style="{width:sourceZoom?'200%':'100%',maxWidth:'none'}" :src="preview.image" :alt="`Actual source page ${preview.page} of ${current?.original_name}, revision ${preview.revision}`"/></div><div class="source-fields"><div v-for="r in selectedRows" :key="key(r)" class="suggestion-field"><label class="review-check"><input v-model="drafts[key(r)].selected" type="checkbox" :disabled="saving||(r.field==='document_date'&&!r.available)"/>Accept suggested {{r.field==='title'?'title':'date'}}</label><label class="review-value">{{r.field==='title'?'Title':'Date'}} to save<input v-model="drafts[key(r)].value" :type="r.field==='title'?'text':'date'" :maxlength="r.field==='title'?250:10" :disabled="saving" :aria-invalid="drafts[key(r)].selected&&!valid(r)"/></label><div class="field-evidence"><span>Current: {{r.current||'Blank'}} · {{r.source==='filename'?'Filename':`Page ${r.page}`}}: {{r.evidence}}</span><button class="text-tool" :disabled="saving" @click="dismiss(r)">Dismiss {{r.field==='title'?'title':'date'}}</button></div><small v-if="r.status!=='proposed'">{{r.note}}</small></div><label class="review-page-picker">Inspect another source page<input v-model.number="pages[selected]" type="number" min="1" :max="current?.page_count" :placeholder="String(selectedRows[0]?.page||1)"/><button class="text-tool" :disabled="dirty||saving" @click="load()">Read page</button></label><p class="review-footnote">Metadata changes trigger index-layout review. Original PDF bytes remain unchanged. Source text and OCR are not legally verified.</p></div></section>
 </div>
</section>
</template>
